import type {EmailDesignSettings} from './types';

interface ColorPickerRegistry {
    // Marks a color picker as open (or in the process of opening) and stores a
    // callback that closes it. Returns an unregister function.
    register: (id: string, close: () => void) => () => void;
    // Marks a previously-registered color picker as closed.
    unregister: (id: string) => void;
    // Whether any color picker is currently open or opening. Synchronous so it
    // can be consulted from within a keydown handler.
    isOpen: () => boolean;
    // Closes every open color picker.
    closeAll: () => void;
}

interface EmailDesignContextValue {
    settings: EmailDesignSettings;
    onSettingsChange: (updates: Partial<EmailDesignSettings>) => void;
    accentColor: string;
    colorPickers: ColorPickerRegistry;
}

const EmailDesignContext = createContext<EmailDesignContextValue | undefined>(undefined);

interface EmailDesignProviderProps {
    settings: EmailDesignSettings;
    onSettingsChange: (updates: Partial<EmailDesignSettings>) => void;
    accentColor: string;
    children: ReactNode;
}

export const EmailDesignProvider = ({settings, onSettingsChange, accentColor, children}: EmailDesignProviderProps) => {
    const openPickersRef = useRef<Map<string, () => void>>(new Map());

    const colorPickers = useMemo<ColorPickerRegistry>(() => ({
        register: (id, close) => {
            openPickersRef.current.set(id, close);
            return () => {
                openPickersRef.current.delete(id);
            };
        },
        unregister: (id) => {
            openPickersRef.current.delete(id);
        },
        isOpen: () => openPickersRef.current.size > 0,
        closeAll: () => {
            const closers = Array.from(openPickersRef.current.values());
            openPickersRef.current.clear();
            closers.forEach(close => close());
        }
    }), []);

    const value = useMemo<EmailDesignContextValue>(() => ({
        settings,
        onSettingsChange,
        accentColor,
        colorPickers
    }), [settings, onSettingsChange, accentColor, colorPickers]);

    return (
        <EmailDesignContext.Provider value={value}>
            {children}
        </EmailDesignContext.Provider>
    );
};

export const useEmailDesign = (): EmailDesignContextValue => {
    const ctx = useContext(EmailDesignContext);
    if (!ctx) {
        throw new Error('useEmailDesign must be used within an EmailDesignProvider');
    }
    return ctx;
};

// Returns the color picker registry when rendered within an EmailDesignProvider,
// otherwise a no-op registry so generic color pickers keep working standalone.
export const useColorPickerRegistry = (): ColorPickerRegistry => {
    const ctx = useContext(EmailDesignContext);
    const fallback = useRef<ColorPickerRegistry>({
        register: () => () => {},
        unregister: () => {},
        isOpen: () => false,
        closeAll: () => {}
    });

    return ctx?.colorPickers ?? fallback.current;
