);

describe('scratch escape', function () {
    it('keeps modal open when Escape pressed with picker mounted', function () {
        let closed = false;
        renderModal(() => {
            closed = true;
        });
        fireEvent.click(screen.getByText('Button color'));
        const content = document.querySelector('[data-radix-popper-content-wrapper], [role="dialog"] [role="textbox"]');
